import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        int value;
        List<Node> children;

        Node(int value) {
            this.value = value;
            this.children = new ArrayList<>();
        }
    }

    static class NaryTree {
        Node root;
        Map<Integer, Node> nodeMap;

        NaryTree() {
            nodeMap = new HashMap<>();
        }

        void insert(int parentValue, int value) {
            Node parent = nodeMap.get(parentValue);
            if (parent == null) {
                // Parent doesn't exist, create it as root if value is being inserted
                Node newNode = new Node(value);
                nodeMap.put(value, newNode);
                if (root == null) {
                    root = newNode;
                } else {
                    // Insert as child of root
                    root.children.add(newNode);
                }
            } else {
                Node newNode = new Node(value);
                nodeMap.put(value, newNode);
                parent.children.add(newNode);
            }
        }

        void delete(int value) {
            if (root == null) return;

            if (root.value == value) {
                root = null;
                nodeMap.clear();
                return;
            }

            deleteHelper(root, value);
        }

        private boolean deleteHelper(Node current, int value) {
            if (current == null) return false;

            Iterator<Node> iter = current.children.iterator();
            while (iter.hasNext()) {
                Node child = iter.next();
                if (child.value == value) {
                    iter.remove();
                    removeFromMapAndDescendants(child);
                    return true;
                }
                if (deleteHelper(child, value)) {
                    return true;
                }
            }
            return false;
        }

        private void removeFromMapAndDescendants(Node node) {
            nodeMap.remove(node.value);
            for (Node child : node.children) {
                removeFromMapAndDescendants(child);
            }
        }

        List<Integer> preorder() {
            List<Integer> result = new ArrayList<>();
            preorderHelper(root, result);
            return result;
        }

        private void preorderHelper(Node node, List<Integer> result) {
            if (node == null) return;
            result.add(node.value);
            for (Node child : node.children) {
                preorderHelper(child, result);
            }
        }

        List<Integer> postorder() {
            List<Integer> result = new ArrayList<>();
            postorderHelper(root, result);
            return result;
        }

        private void postorderHelper(Node node, List<Integer> result) {
            if (node == null) return;
            for (Node child : node.children) {
                postorderHelper(child, result);
            }
            result.add(node.value);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        NaryTree tree = new NaryTree();

        for (int i = 0; i < n; i++) {
            String line = br.readLine().trim();
            if (line.isEmpty()) continue;

            String[] parts = line.split("\\s+");

            if (parts[0].equals("insert")) {
                int parentValue = Integer.parseInt(parts[1]);
                int value = Integer.parseInt(parts[2]);
                tree.insert(parentValue, value);
            } else if (parts[0].equals("delete")) {
                int value = Integer.parseInt(parts[1]);
                tree.delete(value);
            } else if (parts[0].equals("preorder")) {
                List<Integer> result = tree.preorder();
                System.out.println(String.join(" ", result.stream().map(String::valueOf).toArray(String[]::new)));
            } else if (parts[0].equals("postorder")) {
                List<Integer> result = tree.postorder();
                System.out.println(String.join(" ", result.stream().map(String::valueOf).toArray(String[]::new)));
            }
        }
    }
}
